"""xtest bundle for the 51 trait questions on the common structure (ledger L690). Each trait is one noul (yes/no) question whose instruction is the question text from the frozen spec specs/traits_v0.json; no wording by hand except the mechanical paraphrase P (statement form), generated by rule and checked by eye before any run. Items: a blind random sample of devq items (sha256 of the id decides, no rater's answer is used).
    python3 bundle_traits.py --items-n 150 --out runs/xtest/B4"""
import argparse, hashlib, json, os, re, sys
sys.path.insert(0, "/workspace/jevbench"); from jevbench.tasks import Task, write_jsonl, dataset_hash
W = "/workspace/knowledge_pipeline/projects/world-state"
def third(v):
    if re.search(r"(s|sh|ch|x|z)$", v): return v + "es"
    if re.search(r"[^aeiou]y$", v): return v[:-1] + "ies"
    return v + "s"
MANUAL = {"Would an ordinary household notice the effect within a month?": "An ordinary household would notice the effect within a month.", "Would a business owner need to change a decision because of this?": "A business owner would need to change a decision because of this.", "Is the change the main subject of the story?": "The change is the main subject of the story.", "Does the story only mention the change in passing?": "The story only mentions the change in passing."}
def frame(q):
    return f"Read the news item, then answer this question with yes or no only. Question: {q}"
def paraphrase(q):
    if q in MANUAL: s = MANUAL[q]
    else:
        m = re.match(r"Does the story (\w+)(.*)\?$", q); assert m, q; s = f"The story {third(m.group(1))}{m.group(2)}."
    return f"Consider this statement about the item: \"{s}\" Answer yes if the statement is true of the item, no if it is not."
if __name__ == "__main__":
    ap = argparse.ArgumentParser(); ap.add_argument("--items-n", type=int, default=150); ap.add_argument("--out", required=True); ap.add_argument("--show", action="store_true"); a = ap.parse_args()
    Q = json.load(open(f"{W}/specs/traits_v0.json"))["questions"]
    if a.show:
        for x in Q: print(x["id"], "|", x["question"], "\n      ->", re.search(r'"(.*?)"', paraphrase(x["question"])).group(1))
        sys.exit()
    txt = {r["id"]: r["text"] for r in map(json.loads, open(f"{W}/runs/pulse/queue_texts.jsonl"))}; dq = [json.loads(l)["item_id"] for l in open(f"{W}/runs/pulse/devq/labels.jsonl")]
    ids = sorted((i for i in dq if i in txt), key=lambda i: hashlib.sha256(("traits-B4|" + i).encode()).hexdigest())[:a.items_n]
    os.makedirs(a.out, exist_ok=True); items_path = f"{a.out}/items.jsonl"
    with open(items_path, "w") as f:
        for i in ids: f.write(json.dumps({"id": i, "text": txt[i]}) + "\n")
    tasks = {"A": [], "P": [], "Q": []}
    for v in "APQ":
        for x in Q:
            ins = x["question"] if v == "A" else paraphrase(x["question"]) if v == "P" else frame(x["question"])
            for i in ids: tasks[v].append(Task(id=f"t_{x['id']}:{i}", family=f"t_{x['id']}", state=txt[i], question={"type": "noul", "instructions": ins}, labels=["no", "yes"], expected=None, split="private", group=f"t_{x['id']}:{i}", provenance={"bundle": os.path.basename(a.out), "variant": v, "item": i, "stratum": "random"}))
    for v in tasks:
        for t in tasks[v]: t.validate()
        write_jsonl(tasks[v], f"{a.out}/tasks_{v}.jsonl")
    H = lambda s: hashlib.sha256(s.encode()).hexdigest(); g = open(f"{W}/specs/traits_v0.json").read()
    bundle = {"id": os.path.basename(a.out), "guideline_file": "specs/traits_v0.json", "guideline_sha256": H(g), "items_file": items_path, "items_sha256": H(open(items_path).read()), "n_items": len(ids), "dataset_hash": {v: dataset_hash(tasks[v]) for v in tasks},
              "instruction_sha256": {v: {f"t_{x['id']}": H(x["question"] if v == "A" else paraphrase(x["question"]) if v == "P" else frame(x["question"])) for x in Q} for v in "APQ"}, "question_types": {f"t_{x['id']}": "noul" for x in Q}, "fields": [f"t_{x['id']}" for x in Q], "groups": {f"t_{x['id']}": x["group"] for x in Q},
              "decoding_contract": {"temperature": 0, "reasoning": "off or declared equal", "structured_output": "same label set for all"}, "selection": {"blind": True, "design": {"note": "random by sha256 of id, no rater output used", "weights": {i: 1.0 for i in ids}, "strata": {i: "random" for i in ids}}}}
    json.dump(bundle, open(f"{a.out}/bundle.json", "w"), indent=1); print("bundle", bundle["id"], len(ids), "items x", len(Q), "traits =", len(tasks["A"]), "tasks per variant")
